class Solution {
    public:long long maximumScoreAfterOperations(vector<vector<int>>& edges,vector<int>& values){
        int n=values.size();
        vector<vector<int>> graph(n);
        for(auto& edge:edges){
            graph[edge[0]].push_back(edge[1]);
            graph[edge[1]].push_back(edge[0]);
        }
        vector<int> parent(n,-1),order;
        parent[0]=0;
        stack<int> pending;
        pending.push(0);
        while(!pending.empty()){
            int node=pending.top();
            pending.pop();
            order.push_back(node);
            for(int next:graph[node])if(parent[next]==-1){
                parent[next]=node;
                pending.push(next);
            }
        }
        long long total=accumulate(values.begin(),values.end(),0LL);
        vector<long long> keep(n);
        for(int index=n-1;index>=0;--index){
            int node=order[index];
            long long children=0;
            bool leaf=true;
            for(int next:graph[node])if(parent[next]==node){
                leaf=false;
                children+=keep[next];
            }
            keep[node]=leaf?values[node]:min<long long>(values[node],children);
        }
        return total-keep[0];
    }
};
